/* CanteenLedger: entirely local, offline financial ledger. */
(()=>{'use strict';
const C=globalThis.CanteenCore,E=globalThis.CanteenExports,$=(s,base=document)=>base.querySelector(s),$$=(s,base=document)=>[...base.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=n=>`<svg class="icon" aria-hidden="true"><use href="#i-${n}"/></svg>`;
const dateLong=s=>C.atDate(s).toLocaleDateString('en-PH',{month:'short',day:'numeric',year:'numeric'});
const dateShort=s=>C.atDate(s).toLocaleDateString('en-PH',{month:'short',day:'numeric'});
const numPeso=cent=>((cent||0)/100).toFixed(2);
const money=C.money;
let today=C.isoDate();
const menu=[['dashboard','Dashboard','layout'],['sale','Record Sale','arrow-up'],['expense','Expenses','arrow-down'],['weekly','Weekly Tracker','calendar'],['monthly','Monthly Tracker','chart'],['transactions','Transactions','list'],['coop','Cooperative Money','wallet'],['reports','Reports','file'],['settings','Settings','settings']];
const dbName='canteenledger_data_v1',store='data';let db,state=C.blank(),page='dashboard',busy=false,renderCount=0;
const ui={chart:'week',week:C.weekStart(today),month:today.slice(0,7),saleDraft:{date:today,fund:'Food',amount:'',correction:''},saleEdit:null,expenseEdit:null,expenseReceipt:null,history:{search:'',type:'all',from:'',to:'',min:'',max:'',category:'all'},reportType:'monthly',reportDate:today,reportData:null,closingDate:today};
function openDB(){return new Promise((resolve,reject)=>{if(!('indexedDB' in globalThis))return reject(Error('IndexedDB is not supported in this browser.'));const req=indexedDB.open(dbName,1);req.onupgradeneeded=()=>{if(!req.result.objectStoreNames.contains(store))req.result.createObjectStore(store);};req.onerror=()=>reject(req.error);req.onsuccess=()=>resolve(req.result);});}
function dbGet(){return new Promise((resolve,reject)=>{const r=db.transaction(store,'readonly').objectStore(store).get('main');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
function dbPut(obj){return new Promise((resolve,reject)=>{const t=db.transaction(store,'readwrite');t.objectStore(store).put(obj,'main');t.oncomplete=()=>resolve();t.onerror=()=>reject(t.error);t.onabort=()=>reject(t.error||Error('Local database save was interrupted.'));});}
function toast(msg,err=false){const node=document.createElement('div');node.className='toast'+(err?' error':'');node.textContent=msg;$('#toastRoot').append(node);setTimeout(()=>node.remove(),4200);}
async function mutate(fn,success='Saved offline'){if(busy)return false;busy=true;try{const draft=structuredClone(state);const result=await fn(draft);if(result===false)return false;await dbPut(draft);state=draft;updateTheme();render();if(success)toast(success);return true;}catch(e){console.error(e);toast(e.message||'Could not save. No changes were committed.',true);return false;}finally{busy=false;}}
function audit(s,action,before,after,reason=''){s.audit.unshift({id:C.uid(),action,date:new Date().toISOString(),transactionId:after?.id||before?.id||'',before:before?structuredClone(before):null,after:after?structuredClone(after):null,reason});}
const byId=id=>state.transactions.find(t=>t.id===id);
const validDate=s=>/^\d{4}-\d{2}-\d{2}$/.test(s)&&C.isoDate(C.atDate(s))===s;
function ensureDate(s){if(!validDate(s))throw Error('Select a valid transaction date.');return s;}
const centsInput=(v,opt)=>C.parseMoney(v,opt);
const amountView=delta=>`<span class="${delta>=0?'pos':'neg'}">${delta<0?'−':'+'}${money(Math.abs(delta))}</span>`;
function setHeading(title,sub){$('#crumb').textContent=title;$('#topSubtitle').textContent=sub||'Every peso, accounted for.';}
function navMarkup(id,label,ico,cls='nav-btn'){return `<button class="${cls}${page===id?' active':''}" data-action="nav" data-page="${id}" aria-current="${page===id?'page':'false'}">${icon(ico)}<span>${label}</span></button>`;}
const mobileMenu=[['dashboard','Home','layout'],['sale','Sales','arrow-up'],['expense','Expenses','arrow-down'],['weekly','Weekly','calendar'],['monthly','Monthly','chart'],['transactions','Ledger','list'],['coop','Coop','wallet'],['reports','Reports','file'],['settings','Settings','settings']];
function drawNav(){
  $('#sideNav').innerHTML=menu.map(x=>navMarkup(...x)).join('');
  const bar=$('#mobileNav'),position=bar.scrollLeft;
  bar.innerHTML=mobileMenu.map(x=>navMarkup(...x,'')).join('');
  bar.scrollLeft=position;
  $('#sidebarSchool').textContent=state.settings.school||'School Canteen';
}
function focusMobileTab(){
  const bar=$('#mobileNav'),active=bar?.querySelector('.active');
  if(!active)return;
  const center=active.offsetLeft+active.offsetWidth/2-bar.clientWidth/2;
  bar.scrollTo({left:Math.max(0,center),behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});
}
function render(){today=C.isoDate();renderCount++;drawNav();$('.fab')?.classList.toggle('hidden',page==='sale'||page==='expense'||page==='coop');setHeading((menu.find(x=>x[0]===page)||menu[0])[1]);const m=$('#main');m.innerHTML=({dashboard:dashboardPage,sale:salePage,expense:expensePage,weekly:weeklyPage,monthly:monthlyPage,transactions:transactionsPage,coop:coopPage,reports:reportsPage,settings:settingsPage}[page]||dashboardPage)();if(page==='reports')ui.reportData=makeReport();$('#sidebarSchool').textContent=state.settings.school||'School Canteen';}
function go(to){page=to;if(to!=='sale'){ui.saleEdit=null;}if(to!=='expense'){ui.expenseEdit=null;ui.expenseReceipt=null;}closeModal();render();focusMobileTab();window.scrollTo({top:0,behavior:'instant'});}
const heading=(eyebrow,title,desc,action='')=>`<div class="page-intro"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="subtitle">${desc}</p></div>${action}</div>`;
const cardStat=(label,value,note,ico,cls='')=>`<div class="stat-card ${cls}"><div class="stat-label">${label}<span class="stat-icon">${icon(ico)}</span></div><div class="stat-value">${value}</div><div class="stat-note">${note}</div></div>`;
const tiny=(label,value,cls='')=>`<div class="tiny-stat"><div class="label">${label}</div><strong class="${cls}">${value}</strong></div>`;
function transactionsIn(from,to){return state.transactions.filter(x=>x.date>=from&&x.date<=to);}
function figureChart(kind='week',ref=today){let labels=[],sales=[],expenses=[];if(kind==='week'){const from=C.weekStart(ref);for(let i=0;i<7;i++){const d=C.addDays(from,i),sum=C.dayTotals(state.transactions,d);labels.push(C.atDate(d).toLocaleDateString('en-PH',{weekday:'short'}));sales.push(sum.sales);expenses.push(sum.expenses);}}else if(kind==='month'){const m=ref.slice(0,7),r=C.monthRange(m),days=C.periodDays(r.from,r.to);for(let i=0;i<days.length;i+=7){const part=days.slice(i,i+7),sm=C.summarize(state.transactions,part[0],part.at(-1));labels.push(`W${1+Math.floor(i/7)}`);sales.push(sm.sales);expenses.push(sm.expenses);}}else{const cur=C.atDate(ref);for(let i=5;i>=0;i--){const d=new Date(cur.getFullYear(),cur.getMonth()-i,1),m=C.isoDate(d).slice(0,7),sm=C.summarize(state.transactions,...Object.values(C.monthRange(m)));labels.push(d.toLocaleDateString('en-PH',{month:'short'}));sales.push(sm.sales);expenses.push(sm.expenses);}}const max=Math.max(1,...sales,...expenses),n=labels.length,w=680,h=224,pad=43,usable=w-pad-15,unit=usable/n,bar=Math.min(21,unit*.27);let graph='';for(let l=0;l<=4;l++){const yy=18+l*41;graph+=`<line class="gridline" x1="${pad}" y1="${yy}" x2="${w-5}" y2="${yy}"/><text class="tick" x="${pad-8}" y="${yy+3}" text-anchor="end">${max?Math.round((4-l)*max/4/100).toLocaleString('en-PH'):0}</text>`;}labels.forEach((label,i)=>{const x=pad+i*unit+unit/2,hs=sales[i]/max*155,he=expenses[i]/max*155;graph+=`<rect class="bar bar-sales" tabindex="0" role="button" aria-label="${esc(label)} sales ${esc(money(sales[i]))}" data-chart="${i}" data-kind="${kind}" x="${x-bar-2}" y="${182-hs}" width="${bar}" height="${Math.max(1,hs)}" rx="4"><title>${esc(label)} — Sales ${money(sales[i])}</title></rect><rect class="bar bar-expense" tabindex="0" role="button" aria-label="${esc(label)} expenses ${esc(money(expenses[i]))}" data-chart="${i}" data-kind="${kind}" x="${x+2}" y="${182-he}" width="${bar}" height="${Math.max(1,he)}" rx="4"><title>${esc(label)} — Expenses ${money(expenses[i])}</title></rect><text class="tick" x="${x}" y="205" text-anchor="middle">${label}</text>`;});return `<div class="chart"><svg viewBox="0 0 680 224" role="img" aria-label="Sales and expenses comparison chart">${graph}</svg></div><div class="chart-caption"><span>Values in Philippine pesos (₱)</span><div class="legend"><span><i class="swatch"></i> Sales</span><span><i class="swatch red"></i> Expenses</span></div></div>`;}
const activeTitle=t=>t.type==='sale'?'Sales entry':({income:'Quick income',expense:'Expense',adjustment:'Cash adjustment',coop:'Cooperative money',refund:'Refund',reversal:'Reversal'}[t.type]||t.type);
function recent(t){return `<div class="activity"><div class="activity-dot ${t.delta<0?'expense':''}">${icon(t.delta<0?'arrow-down':'arrow-up')}</div><div class="activity-info"><strong>${esc(t.description)}</strong><small>${dateLong(t.date)} · ${activeTitle(t)} · ${fundLabel(C.fundOf(t))}</small></div><div class="activity-amt">${amountView(t.delta)}</div></div>`;}
function dashboardPage(){const td=C.dayTotals(state.transactions,today),month=C.monthRange(today.slice(0,7)),wk=C.weekRange(today),m=C.summarize(state.transactions,month.from,month.to),w=C.summarize(state.transactions,wk.from,wk.to),recentRows=C.sorted(state.transactions).reverse().slice(0,6);return `<div class="content">${heading('Financial overview','Good day, Treasurer.','Here’s how your canteen funds are doing today.',`<span class="tag">${dateLong(today)}</span>`)}<div class="stats-grid">${cardStat('Available cash balance',money(C.balance(state.transactions)),'Food + Goods + Coop + historical unassigned','wallet','accent')}${cardStat('Sales today',money(td.sales),'Cash received from sales','arrow-up')}${cardStat('Expenses today',money(td.expenses),'Cash paid for expenses','arrow-down')}${cardStat('Net cash movement today',money(td.net),'Includes adjustments and refunds','chart')}</div><div class="second-stats">${tiny('Weekly sales',money(w.sales))}${tiny('Monthly sales',money(m.sales))}${tiny('Monthly expenses',money(m.expenses),'neg')}</div>${fundStrip()}<div class="dashboard-columns"><div class="card card-pad"><div class="panel-heading"><div><h2>Financial activity</h2><div class="help">Sales versus expenses by period</div></div><div class="segment">${['week','month','year'].map(p=>`<button data-action="chart-period" data-value="${p}" class="${ui.chart===p?'active':''}">${p==='week'?'Week':p==='month'?'Month':'6 months'}</button>`).join('')}</div></div>${figureChart(ui.chart)}</div><div class="card card-pad"><div class="panel-heading"><div><h2>Recent transactions</h2><div class="help">Your latest recorded activity</div></div><button class="text-btn" data-action="nav" data-page="transactions">View all</button></div><div class="activity-list">${recentRows.length?recentRows.map(recent).join(''):`<div class="empty">${icon('receipt')}No transactions yet.<br>Record your first sale or expense.</div>`}</div><div class="quick-grid"><button class="quick-link" data-action="nav" data-page="sale">${icon('plus')} Record a sale</button><button class="quick-link" data-action="nav" data-page="expense">${icon('arrow-down')} Add expense</button></div></div></div><div class="notice" style="margin-top:17px"><strong>Understanding the numbers:</strong> Net cash movement = cash received − cash paid, including refunds and adjustments. It is <strong>not accounting profit</strong>. Inventory costs and other accrual adjustments are not calculated as profit.</div></div>`;}
const opts=(array,selected)=>array.map(s=>`<option value="${esc(s)}" ${String(s)===String(selected)?'selected':''}>${esc(s)}</option>`).join('');
const field=(name,label,value='',type='text',extra='')=>`<div class="field"><label for="${name}">${label}</label><input id="${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}></div>`;
const fundOptions=(selected='Food')=>[['Food','Foods'],['Goods','Goods'],['Coop','Cooperative Money']].map(([v,label])=>`<option value="${v}" ${v===selected?'selected':''}>${label}</option>`).join('');
const fundLabel=f=>({Food:'Foods',Goods:'Goods',Coop:'Cooperative Money',Legacy:'Unassigned (older records)'})[f]||'Unassigned (older records)';
const fundStrip=()=>{const b=C.fundsBalances(state.transactions);return `<div class="fund-grid">${['Food','Goods','Coop','Legacy'].map(f=>`<div class="fund-card"><div class="fund-tag">${esc(fundLabel(f))}</div><strong class="${b[f]<0?'neg':''}">${money(b[f])}</strong><small>${f==='Legacy'?'From earlier records without a fund':f==='Coop'?'Deposits minus coop spending':'Sales less expenses and refunds'}</small></div>`).join('')}</div>`};
function coopPage(){const balance=C.fundBalance(state.transactions,'Coop'),members=[...state.members].sort((a,b)=>a.archived-b.archived||a.name.localeCompare(b.name)),rows=C.ledger(state.transactions).filter(t=>C.fundOf(t)==='Coop').reverse().slice(0,12);return `<div class="content">${heading('Cooperative fund & membership','Cooperative Money','Add or withdraw cooperative cash. Manage members separately from transactions.')}<div class="coop-intro"><div class="coop-hero"><span class="fund-tag">Available Cooperative Money</span><strong>${money(balance)}</strong><span>Deposits and credits − withdrawals and expenses charged to Coop</span></div><div class="coop-buttons"><button type="button" class="btn btn-primary" data-action="coop-money">${icon('plus')} Add / subtract money</button><button type="button" class="btn" data-action="member-add">${icon('plus')} Add member</button></div></div><div class="detail-grid"><div class="card card-pad"><div class="panel-heading"><div><h2>Cooperative members</h2><div class="help">Removing a member keeps their past transactions.</div></div><span class="tag">${state.members.filter(m=>!m.archived).length} active</span></div>${members.length?members.map(m=>`<div class="member-row ${m.archived?'archived':''}"><div class="member-avatar">${esc(m.name.charAt(0).toUpperCase())}</div><div class="activity-info"><strong>${esc(m.name)}</strong><small>${esc(m.role||'Member')}${m.archived?' · Removed':''}</small></div><div class="actions-inline"><button type="button" class="icon-btn" data-action="member-edit" data-id="${esc(m.id)}" aria-label="Edit member">${icon('edit')}</button><button type="button" class="icon-btn" data-action="member-toggle" data-id="${esc(m.id)}" aria-label="${m.archived?'Restore':'Remove'} member">${icon(m.archived?'refresh':'trash')}</button></div></div>`).join(''):'<div class="empty">No cooperative members yet. Add a member to begin.</div>'}</div><div class="card card-pad"><div class="panel-heading"><div><h2>Cooperative cash activity</h2><div class="help">Includes expenses deducted from cooperative money</div></div><button class="text-btn" data-action="nav" data-page="transactions">All entries</button></div>${rows.length?rows.map(recent).join(''):'<div class="empty">No cooperative money recorded yet.</div>'}</div></div></div>`;}
function coopMoneyModal(){openModal('Add or subtract cooperative money',`<form id="coopForm" class="form-grid">${field('coopDate','Transaction date',today,'date','required')}<div class="field"><label for="coopDirection">Action</label><select id="coopDirection"><option value="in">Add cooperative money (+)</option><option value="out">Subtract cooperative money (−)</option></select></div>${field('coopAmount','Amount (₱)','','text','inputmode="decimal" required')}<div class="field"><label for="coopMember">Related member (optional)</label><select id="coopMember"><option value="">General cooperative funds</option>${state.members.filter(m=>!m.archived).map(m=>`<option value="${esc(m.id)}">${esc(m.name)}</option>`).join('')}</select></div><div class="full">${field('coopReason','Reason / source of money','','text','required placeholder="e.g. Member contribution, withdrawal"')}</div><div class="field full"><label for="coopRemarks">Remarks (optional)</label><textarea id="coopRemarks"></textarea></div><div class="full notice">This changes <strong>Cooperative Money only</strong>. To record a cooperative purchase with an expense category and receipt, use the Expenses page and choose Cooperative Money.</div><div class="full form-footer"><button type="button" class="btn" data-action="modal-close">Cancel</button><button type="submit" class="btn btn-primary">Save cooperative entry</button></div></form>`);}
function memberModal(member){openModal(member?'Edit cooperative member':'Add cooperative member',`<form id="memberForm" class="form-grid"><input type="hidden" id="memberId" value="${esc(member?.id||'')}">${field('memberName','Member name',member?.name||'','text','required maxlength="120"')}${field('memberRole','Role / position (optional)',member?.role||'','text','maxlength="120"')}<div class="full form-footer"><button type="button" class="btn" data-action="modal-close">Cancel</button><button type="submit" class="btn btn-primary">Save member</button></div></form>`);}
async function submitCoop(){const date=ensureDate($('#coopDate').value),memberId=$('#coopMember').value,m=state.members.find(x=>x.id===memberId),tx=C.makeCoop({date,direction:$('#coopDirection').value,amount:$('#coopAmount').value,description:$('#coopReason').value,remarks:$('#coopRemarks').value,memberId,memberName:m?.name||''});const ok=await mutate(s=>{s.transactions.push(tx);audit(s,'Cooperative '+(tx.delta>0?'deposit':'withdrawal'),null,tx);},'Cooperative balance updated');if(ok)closeModal();}
async function submitMember(){const id=$('#memberId').value,name=$('#memberName').value.trim(),role=$('#memberRole').value.trim();if(!name||name.length>120)throw Error('Enter a member name of up to 120 characters.');const ok=await mutate(s=>{const old=s.members.find(m=>m.id===id);if(old){const before=structuredClone(old);old.name=name;old.role=role;audit(s,'Edit cooperative member',before,old);}else{const member={id:C.uid(),name,role,archived:false,addedAt:new Date().toISOString()};s.members.push(member);audit(s,'Add cooperative member',null,member);}},'Member saved');if(ok)closeModal();}
function salePage(){
 const edit=ui.saleEdit?byId(ui.saleEdit):null,draft=ui.saleDraft;
 return `<div class="content">${heading('Money coming in',edit?'Correct a sale':'Record daily sales',edit?'Corrections preserve the original values in audit history.':'Choose Foods or Goods and enter the total money received. No product names, quantities, or remarks required.')}
 <div class="card card-pad sales-simple">
  <div class="panel-heading"><div><h2>Sales entry</h2><div class="help">Sales increase the chosen fund. Expenses reduce its available cash.</div></div><span class="tag">Money in</span></div>
  <form id="saleForm" class="form-grid">
   ${field('saleDate','Transaction date',draft.date,'date','required')}
   <div class="field"><label for="saleFund">Sales belong to</label><select id="saleFund"><option value="Food" ${draft.fund!=='Goods'?'selected':''}>Foods</option><option value="Goods" ${draft.fund==='Goods'?'selected':''}>Goods</option></select></div>
   <div class="full">${field('saleAmount','Total sales received (₱)',draft.amount||'','text','required inputmode="decimal" autocomplete="off" placeholder="0.00"').replace('<div class="field">','<div class="field">')}</div>
   ${edit?field('saleCorrection','Reason for correction',draft.correction||'','text','class="full" placeholder="Why was this changed?" required'):''}
   <div class="full notice">An expense subtracts from the selected fund's <strong>available cash</strong>, not from historical sales. Net cash movement is not accounting profit.</div>
   <div class="full form-footer">${edit?`<button type="button" class="btn" data-action="cancel-edit">Cancel correction</button>`:''}<button type="submit" class="btn btn-primary">${icon('check')} ${edit?'Save corrected sale':'Record sale offline'}</button></div>
  </form>
 </div></div>`;
}
function expensePage(){const edit=ui.expenseEdit?byId(ui.expenseEdit):null;return `<div class="content">${heading('Money going out',edit?'Correct an expense':'Record an expense','Choose exactly which cash fund paid for this expense. The amount is deducted only once.')}<div class="card card-pad" style="max-width:850px"><div class="panel-heading"><div><h2>Expense details</h2><div class="help">Food · Goods · Cooperative Money</div></div><span class="tag">Money out</span></div><form id="expenseForm" class="form-grid">${field('expenseDate','Date paid',edit?.date||today,'date','required')}${field('expenseAmount','Amount paid (₱)',edit?numPeso(-edit.delta):'','text','inputmode="decimal" required')}<div class="field"><label for="expenseFund">Paid from / deduct from</label><select id="expenseFund">${fundOptions(edit?.fund||'Food')}</select><small>Only this fund's balance decreases. The expense stays in the ledger.</small></div>${field('expenseDescription','What was purchased?',edit?.description||'','text','required placeholder="e.g. Ingredients or supplies"')}<div class="field"><label for="expenseCategory">Expense category</label><select id="expenseCategory">${opts(state.expenseCategories,edit?.category||'Food ingredients')}</select></div><div class="field full"><label for="expenseRemarks">Remarks (optional)</label><textarea id="expenseRemarks">${esc(edit?.remarks||'')}</textarea></div><div class="field full"><label for="expenseReceipt">Receipt image (optional)</label><input type="file" id="expenseReceipt" accept="image/*" class="file-input"><div id="receiptPreview">${ui.expenseReceipt||edit?.receipt?`<img class="receipt-preview" src="${esc(ui.expenseReceipt||edit?.receipt)}" alt="Receipt"><button type="button" class="btn btn-small" data-action="remove-receipt">Remove receipt</button>`:''}</div></div>${edit?field('expenseCorrection','Reason for correction','','text','class="full" required'):''}<div class="full form-footer">${edit?`<button type="button" class="btn" data-action="cancel-edit">Cancel</button>`:''}<button class="btn btn-primary" type="submit">${icon('check')} ${edit?'Save corrected expense':'Save expense offline'}</button></div></form></div></div>`;}
function weeklyPage(){const r=C.weekRange(ui.week),weekDays=C.periodDays(r.from,r.to),summary=C.summarize(state.transactions,r.from,r.to);const days=weekDays.map(d=>{const s=C.dayTotals(state.transactions,d);return `<div class="day-card ${d===today?'today':''}"><div class="dayname">${C.atDate(d).toLocaleDateString('en-PH',{weekday:'long'})}</div><div class="daynumber">${C.atDate(d).getDate()}</div><div class="mini-pair">Sales<strong class="pos">${money(s.sales)}</strong></div><div class="mini-pair">Expenses<strong class="neg">${money(s.expenses)}</strong></div><label><input type="checkbox" data-operating="${d}" ${state.operatingDays[d]?'checked':''}> Operated</label></div>`}).join('');return `<div class="content">${heading('Monday to Sunday','Weekly financial tracker','Review each school week without assuming the canteen operated every day.',`<div class="period-head"><button class="icon-btn" data-action="week-shift" data-delta="-7" aria-label="Previous week">${icon('chevron').replace('class="icon"','class="icon" style="transform:rotate(180deg)"')}</button><strong>${dateShort(r.from)} – ${dateLong(r.to)}</strong><button class="icon-btn" data-action="week-shift" data-delta="7" aria-label="Next week">${icon('chevron')}</button></div>`)}<div class="stats-grid">${cardStat('Weekly sales',money(summary.sales),'Sales recorded this week','arrow-up')}${cardStat('Weekly expenses',money(summary.expenses),'Payments recorded this week','arrow-down')}${cardStat('Net cash movement',money(summary.net),'Includes adjustments and refunds','chart')}${cardStat('Closing cash balance',money(summary.closing),`Opening ${money(summary.opening)}`,'wallet','accent')}</div><div class="week-grid">${days}</div><div class="card card-pad"><div class="panel-heading"><div><h2>Week at a glance</h2><div class="help">Daily cash receipts and payments</div></div><span class="tag">${weekDays.filter(d=>state.operatingDays[d]).length} operated days marked</span></div>${figureChart('week',r.from)}<div class="notice" style="margin-top:15px">Tick <strong>Operated</strong> only on dates the canteen was open. Financial entries are retained whether the day is marked open or closed. Opening and closing balances include earlier transactions.</div></div></div>`;}
function groupsProgress(groups,color){if(!groups.length)return '<div class="empty">No entries for this period.</div>';const max=Math.max(...groups.map(x=>x[1]),1);return groups.map(([name,val])=>`<div class="progress-group"><div class="progress-head"><span>${esc(name)}</span><strong>${money(val)}</strong></div><div class="progress-track"><div class="progress-fill ${color||''}" style="width:${Math.max(1,val/max*100)}%"></div></div></div>`).join('');}
function monthlyPage(){const range=C.monthRange(ui.month),sm=C.summarize(state.transactions,range.from,range.to),txn=transactionsIn(range.from,range.to),candidateDays=C.periodDays(range.from,range.to).filter(d=>state.operatingDays[d]||txn.some(t=>t.date===d)),values=candidateDays.map(d=>({date:d,value:C.dayTotals(state.transactions,d).sales})),highest=[...values].sort((a,b)=>b.value-a.value)[0],lowest=[...values].sort((a,b)=>a.value-b.value)[0],saleGroups=C.groupedTotals(state.transactions,range.from,range.to,'saleCategory',['sale','income']),expenseGroups=C.groupedTotals(state.transactions,range.from,range.to,'category',['expense']);return `<div class="content">${heading('Historical financial view','Monthly tracker','Compare monthly totals and review historical records without altering them.',`<div class="period-head"><button class="icon-btn" data-action="month-shift" data-delta="-1" aria-label="Previous month">${icon('chevron').replace('class="icon"','class="icon" style="transform:rotate(180deg)"')}</button><strong>${C.atDate(range.from).toLocaleDateString('en-PH',{month:'long',year:'numeric'})}</strong><button class="icon-btn" data-action="month-shift" data-delta="1" aria-label="Next month">${icon('chevron')}</button></div>`)}<div class="stats-grid">${cardStat('Monthly sales',money(sm.sales),'Food and goods receipts (not profit)','arrow-up')}${cardStat('Monthly expenses',money(sm.expenses),'Total cash paid','arrow-down')}${cardStat('Net cash movement',money(sm.net),'Not accounting profit','chart')}${cardStat('Closing balance',money(sm.closing),`Opening ${money(sm.opening)}`,'wallet','accent')}</div><div class="second-stats">${tiny('Opening balance',money(sm.opening))}${tiny('Highest-sales day',highest?`${dateShort(highest.date)} · ${money(highest.value)}`:'—')}${tiny('Lowest-sales recorded/operated day',lowest?`${dateShort(lowest.date)} · ${money(lowest.value)}`:'—')}</div><div class="card card-pad" style="margin-bottom:18px"><div class="panel-heading"><div><h2>Weekly performance within month</h2><div class="help">Each bar represents consecutive dates grouped by week of month</div></div></div>${figureChart('month',range.from)}</div><div class="detail-grid"><div class="card card-pad"><div class="panel-heading"><h2>Sales by food / goods fund</h2></div>${groupsProgress(saleGroups)}</div><div class="card card-pad"><div class="panel-heading"><h2>Expenses by category</h2></div>${groupsProgress(expenseGroups,'red')}</div></div><p class="small-note" style="margin-top:14px">The lowest-sales day includes dates explicitly marked as operated or having transactions, not automatically every weekend or holiday. Refunds and reversals appear in net cash movement rather than being silently attributed to product sales.</p></div>`;}
function filteredLedger(){const f=ui.history;let rows=C.ledger(state.transactions).reverse();if(f.search)rows=rows.filter(t=>[t.description,t.remarks,t.category,t.id,fundLabel(C.fundOf(t))].join(' ').toLowerCase().includes(f.search.toLowerCase()));if(f.type!=='all')rows=rows.filter(t=>t.type===f.type);if(f.category!=='all')rows=rows.filter(t=>t.category===f.category);if(f.from)rows=rows.filter(t=>t.date>=f.from);if(f.to)rows=rows.filter(t=>t.date<=f.to);if(f.min){try{const min=C.parseMoney(f.min);rows=rows.filter(t=>Math.abs(t.delta)>=min)}catch{}}if(f.max){try{const max=C.parseMoney(f.max);rows=rows.filter(t=>Math.abs(t.delta)<=max)}catch{}}return rows;}
function transactionsPage(){const rows=filteredLedger(),cats=[...new Set(state.transactions.map(t=>t.category).filter(Boolean))].sort();return `<div class="content">${heading('Complete money trail','Transaction ledger','Every transaction, correction, and reversal remains traceable.',`<button class="btn btn-primary" data-action="adjust">${icon('plus')} Cash adjustment</button>`)}<div class="tool-row"><div class="filters"><input type="search" aria-label="Search ledger" placeholder="Search transactions..." data-filter="search" value="${esc(ui.history.search)}"><select aria-label="Type" data-filter="type"><option value="all">All types</option>${opts(['sale','income','expense','coop','adjustment','refund','reversal'],ui.history.type)}</select><select aria-label="Category" data-filter="category"><option value="all">All categories</option>${opts(cats,ui.history.category)}</select><input type="date" aria-label="From date" data-filter="from" value="${esc(ui.history.from)}"><input type="date" aria-label="To date" data-filter="to" value="${esc(ui.history.to)}"><input type="text" inputmode="decimal" aria-label="Minimum pesos" placeholder="Min ₱" style="max-width:85px" data-filter="min" value="${esc(ui.history.min)}"><input type="text" inputmode="decimal" aria-label="Maximum pesos" placeholder="Max ₱" style="max-width:85px" data-filter="max" value="${esc(ui.history.max)}"></div><button class="btn btn-small" data-action="clear-filters">Reset filters</button></div><div class="card"><div class="table-scroll"><table class="data-table"><thead><tr><th>Date & time</th><th>Type</th><th>Description / fund</th><th>Money received</th><th>Money paid</th><th>Running balance</th><th>Actions</th></tr></thead><tbody>${rows.map(t=>`<tr><td>${dateLong(t.date)}<small>${new Date(t.createdAt).toLocaleTimeString('en-PH',{hour:'2-digit',minute:'2-digit'})}</small></td><td><span class="pill ${t.type}">${activeTitle(t)}</span></td><td><strong>${esc(t.description)}</strong><small>${esc(t.category||'')} · ${esc(fundLabel(C.fundOf(t)))} · v${t.version||1}${t.reversedBy?' · Reversed':''}</small></td><td class="pos">${t.delta>0?money(t.delta):'—'}</td><td class="neg">${t.delta<0?money(-t.delta):'—'}</td><td><strong>${money(t.running)}</strong></td><td><div class="actions-inline"><button class="icon-btn" title="View details and audit" aria-label="View transaction" data-action="tx-detail" data-id="${t.id}">${icon('file')}</button>${!t.reversedBy&&!['reversal','refund'].includes(t.type)?`<button class="icon-btn" title="Correct transaction" aria-label="Correct transaction" data-action="tx-edit" data-id="${t.id}">${icon('edit')}</button><button class="icon-btn" title="Reverse transaction" aria-label="Reverse transaction" data-action="tx-reverse" data-id="${t.id}">${icon('refresh')}</button>`:''}${['sale','income'].includes(t.type)&&!t.reversedBy?`<button class="icon-btn" title="Record refund" aria-label="Refund" data-action="refund" data-id="${t.id}">${icon('arrow-down')}</button>`:''}</div></td></tr>`).join('')||`<tr><td colspan="7" class="empty">No transactions match your filters.</td></tr>`}</tbody></table></div></div><div class="notice" style="margin-top:15px">The running balance is calculated chronologically from the entire ledger, even when you filter the displayed entries. “Reverse” adds an offsetting transaction instead of deleting the original. Corrections preserve earlier values in the audit history.</div></div>`;}
function makeReport(){const type=ui.reportType,date=ensureDate(ui.reportDate);let r= type==='daily'?{from:date,to:date}:type==='weekly'?C.weekRange(date):C.monthRange(date.slice(0,7));if(type==='ledger'||type==='expenses'||type==='products')r=C.monthRange(date.slice(0,7));const tx=transactionsIn(r.from,r.to),summary=C.summarize(state.transactions,r.from,r.to),base={title:({daily:'Daily Sales Report',weekly:'Weekly Financial Report',monthly:'Monthly Financial Report',expenses:'Expense Summary',ledger:'Transaction Ledger',products:'Item Sales Summary'})[type],period:dateLong(r.from)+(r.from===r.to?'':' – '+dateLong(r.to)),school:state.settings.school,prepared:state.settings.preparedBy||'',reviewed:state.settings.reviewedBy||'',generated:new Date().toLocaleString('en-PH'),summary:[['Opening cash balance',money(summary.opening)],['Sales and quick income',money(summary.sales)],['Expenses paid',money(summary.expenses)],['Other cash movements',money(summary.other)],['Net cash movement (not profit)',money(summary.net)],['Closing cash balance',money(summary.closing)]],headers:[],rows:[]};
for(const f of ['Food','Goods','Coop','Legacy']){const fundAmount=C.fundBalance(state.transactions,f,C.addDays(r.to,1));if(f!=='Legacy'||fundAmount)base.summary.push([fundLabel(f)+' closing cash',money(fundAmount)]);}
if(type==='products'){base.headers=['Product','Category','Quantity','Total sales'];base.rows=C.productSales(tx,r.from,r.to).map(p=>[p.name,p.category,p.qty,money(p.total)]);}else if(type==='expenses'){base.headers=['Date','Description','Category','Paid from','Money paid','Remarks'];base.rows=tx.filter(t=>t.type==='expense').map(t=>[t.date,t.description,t.category,fundLabel(C.fundOf(t)),money(-t.delta),t.remarks||'']);}else if(type==='ledger'){base.headers=['Date','Type','Description','Fund','Money in','Money out','Running balance'];base.rows=C.ledger(state.transactions).filter(t=>t.date>=r.from&&t.date<=r.to).map(t=>[t.date,activeTitle(t),t.description,fundLabel(C.fundOf(t)),t.delta>0?money(t.delta):'',t.delta<0?money(-t.delta):'',money(t.running)]);}else if(type==='daily'){base.headers=['Time','Transaction','Description','Fund','Category','Money in','Money out'];base.rows=C.sorted(tx).map(t=>[new Date(t.createdAt).toLocaleTimeString('en-PH'),activeTitle(t),t.description,fundLabel(C.fundOf(t)),t.category||'',t.delta>0?money(t.delta):'',t.delta<0?money(-t.delta):'']);}else{base.headers=['Date','Sales','Expenses','Other cash movements','Net cash movement'];base.rows=C.periodDays(r.from,r.to).map(d=>{const s=C.dayTotals(state.transactions,d);return[d,money(s.sales),money(s.expenses),money(s.other),money(s.net)];});}return base;}
function reportPreview(rep){return `<div class="report-preview" id="reportPreview"><h2>${esc(state.settings.school)}</h2><p class="meta">${esc(rep.title)}<br>${esc(rep.period)} · Generated ${esc(rep.generated)}</p><div class="report-summary">${rep.summary.map(([k,v])=>`<div class="progress-head"><span>${esc(k)}</span><strong>${esc(v)}</strong></div>`).join('')}</div><table><thead><tr>${rep.headers.map(x=>`<th>${esc(x)}</th>`).join('')}</tr></thead><tbody>${rep.rows.slice(0,70).map(row=>`<tr>${row.map(v=>`<td>${esc(v)}</td>`).join('')}</tr>`).join('')||`<tr><td colspan="${rep.headers.length}">No records during this report period.</td></tr>`}</tbody></table>${rep.rows.length>70?`<p class="small-note">Preview displays the first 70 rows. Exports include all ${rep.rows.length} rows.</p>`:''}<p class="small-note" style="margin-top:35px">Prepared by: ${esc(rep.prepared||'__________________')}<br>Reviewed by: ${esc(rep.reviewed||'__________________')}</p></div>`;}
function reportsPage(){const rep=makeReport();return `<div class="content">${heading('Shareable, printable records','Financial reports','Create meeting-ready reports without an internet connection.')}<div class="report-grid"><div class="card card-pad"><h2 style="margin-bottom:20px">Generate report</h2><div class="form-grid" style="grid-template-columns:1fr"><div class="field"><label for="reportType">Report type</label><select id="reportType">${[['daily','Daily Sales Report'],['weekly','Weekly Financial Report'],['monthly','Monthly Financial Report'],['expenses','Expense Summary'],['ledger','Transaction Ledger'],['products','Item Sales Summary']].map(([v,t])=>`<option value="${v}" ${v===ui.reportType?'selected':''}>${t}</option>`).join('')}</select></div>${field('reportDate','Select date (used to determine report period)',ui.reportDate,'date')}<button class="btn btn-primary" data-action="report-update">${icon('refresh')} Refresh preview</button></div><hr class="divider"><h3 style="margin-bottom:12px">Export report</h3><div class="group-row"><button class="btn btn-small" data-action="export-report" data-format="xlsx">${icon('download')} Excel (.xlsx)</button><button class="btn btn-small" data-action="export-report" data-format="csv">${icon('download')} CSV</button><button class="btn btn-small" data-action="export-report" data-format="pdf">${icon('download')} PDF</button></div><button style="margin-top:13px" class="btn btn-small" data-action="print-report">${icon('file')} Print preview</button><div class="notice" style="margin-top:23px">Reports use your saved historical transaction values. CSV, genuine XLSX, and PDF files are created locally, without a remote service.</div></div><div class="card card-pad">${reportPreview(rep)}</div></div></div>`;}
function settingsPage(){const s=state.settings;return `<div class="content">${heading('Workspace preferences','Settings & backups','Configure your school details, security, and storage.')}<div class="detail-grid"><div class="card card-pad"><div class="panel-heading"><h2>School & report details</h2></div><form id="settingsForm" class="form-grid">${field('schoolName','School / Canteen name',s.school,'text','required class="full"')}${field('preparedBy','Prepared by (optional)',s.preparedBy||'')}${field('reviewedBy','Reviewed by (optional)',s.reviewedBy||'')}<div class="field full"><label for="themeSelect">Theme</label><select id="themeSelect"><option value="light" ${s.theme==='light'?'selected':''}>Light — Warm cream</option><option value="dark" ${s.theme==='dark'?'selected':''}>Dark — Deep forest</option></select></div><div class="full form-footer"><button class="btn btn-primary" type="submit">${icon('check')} Save preferences</button></div></form></div><div class="card card-pad"><div class="panel-heading"><h2>Cash controls</h2></div><p class="subtitle" style="margin-bottom:17px">Record an opening balance, adjustment, or end-of-day count.</p><div class="group-row"><button class="btn" data-action="adjust">${icon('plus')} Cash adjustment / opening</button><button class="btn" data-action="closing">${icon('receipt')} End-of-day closing</button></div><hr class="divider"><h3 style="margin-bottom:12px">Recent cash closings</h3>${state.closings.length?state.closings.slice(0,4).map(x=>`<div class="activity"><div class="activity-info"><strong>${dateLong(x.date)}</strong><small>Expected ${money(x.expected)} · Counted ${money(x.counted)}</small></div><span class="${x.difference<0?'neg':'pos'}">${money(x.difference)}</span></div>`).join(''):`<p class="small-note">No end-of-day closings recorded.</p>`}</div><div class="card card-pad"><div class="panel-heading"><h2>Backup & recovery</h2></div><p class="subtitle" style="margin-bottom:15px">Your records are stored on this device in IndexedDB. Export a backup regularly, especially before uninstalling or clearing browser data.</p><div class="group-row"><button class="btn btn-primary" data-action="backup">${icon('download')} Download JSON backup</button><button class="btn" data-action="restore">${icon('refresh')} Restore backup</button><input id="restoreInput" type="file" accept=".json,application/json" hidden></div><div class="notice warn" style="margin-top:16px">Uninstalling this app or clearing its data can permanently erase locally stored records. A JSON backup can restore transactions, images, products, preferences, and audit history. No automatic cloud backup is performed.</div><button class="btn btn-small" style="margin-top:12px" data-action="persist-storage">Request persistent device storage</button></div><div class="card card-pad"><div class="panel-heading"><h2>Security & categories</h2></div><div class="group-row"><button class="btn" data-action="pin">${icon('lock')} ${s.pin?'Change / remove PIN':'Set optional app PIN'}</button><button class="btn" data-action="categories">${icon('edit')} Expense categories</button></div><p class="small-note" style="margin-top:14px">The optional PIN is a convenience lock, not encrypted storage. Android system biometrics are not enabled in this build. Do not use this app as the only copy of sensitive financial documents.</p></div></div><div class="card card-pad" style="margin-top:18px"><div class="panel-heading"><div><h2>Audit history</h2><div class="help">Original and changed values are retained for corrections</div></div><span class="tag">${state.audit.length} events</span></div>${state.audit.length?state.audit.slice(0,25).map(a=>`<div class="audit-item"><strong>${esc(a.action)}</strong><small>${new Date(a.date).toLocaleString('en-PH')} ${a.reason?'· Reason: '+esc(a.reason):''}</small><button class="text-btn" data-action="audit-detail" data-id="${a.id}">Inspect before / after</button></div>`).join(''):'<p class="small-note">No changes yet.</p>'}</div></div>`;}
function openModal(title,body,foot='',small=false){$('#modalRoot').innerHTML=`<div class="overlay" data-overlay><div class="modal ${small?'small':''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-head"><div><h2>${esc(title)}</h2></div><button class="icon-btn" data-action="modal-close" aria-label="Close">${icon('close')}</button></div><div class="modal-body">${body}</div>${foot?`<div class="modal-foot">${foot}</div>`:''}</div></div>`;$('#modalRoot .modal input:not([type=hidden]),#modalRoot .modal select')?.focus();}
function closeModal(){$('#modalRoot').innerHTML='';}
let confirmCallback=null;
function ask(title,message,callback,label='Confirm',danger=false){confirmCallback=callback;openModal(title,`<p class="subtitle" style="font-size:13px">${esc(message)}</p>`,`<button class="btn" data-action="modal-close">Cancel</button><button class="btn ${danger?'btn-danger':'btn-primary'}" data-action="confirm-run">${esc(label)}</button>`,true);}
function adjustmentModal(tx){openModal(tx?'Correct cash adjustment':'Cash adjustment / opening balance',`<form id="adjustForm" class="form-grid">${field('adjustDate','Date',tx?.date||today,'date','required')}<div class="field"><label for="adjustFund">Which fund?</label><select id="adjustFund">${fundOptions(tx?.fund||'Food')}</select></div>${field('adjustAmount','Signed amount in ₱ (e.g. 5000 or -200)',tx?numPeso(tx.delta):'','text','inputmode="decimal" required')}${field('adjustReason','Reason',tx?.description||'','text','required')}<div class="field full"><label for="adjustNotes">Additional remarks</label><textarea id="adjustNotes">${esc(tx?.remarks||'')}</textarea></div>${tx?field('adjustCorrection','Correction reason','','text','required'):''}<input type="hidden" name="editId" value="${esc(tx?.id||'')}"><div class="form-footer full"><button type="button" class="btn" data-action="modal-close">Cancel</button><button class="btn btn-primary" type="submit">Save adjustment</button></div></form><div class="notice" style="margin-top:13px">Adjustments change the chosen fund and the overall available cash. Cooperative additions and withdrawals can also be recorded in the Cooperative Money page.</div>`);}
function closingModal(){const date=ui.closingDate,expected=C.balance(state.transactions,C.addDays(date,1)),prev=state.closings.filter(x=>x.date===date).at(-1);openModal('End-of-day cash reconciliation',`<form id="closingForm" class="form-grid">${field('closingDate','Closing date',date,'date','required')}${field('closingCounted','Cash physically counted (₱)',prev?numPeso(prev.counted):'','text','inputmode="decimal" required')}<div class="full notice">Expected available cash through this date: <strong id="closingExpected">${money(expected)}</strong>. Reconciliation does not change your recorded cash balance.</div><div class="full"><strong class="section-title">Difference: <span id="closingDiff">${prev?money(prev.difference):'—'}</span></strong></div><div class="field full"><label for="closingRemarks">Remarks (optional)</label><textarea id="closingRemarks" placeholder="Reason for shortage or overage">${esc(prev?.remarks||'')}</textarea></div><div class="full form-footer"><button class="btn" type="button" data-action="modal-close">Cancel</button><button class="btn btn-primary" type="submit">${icon('check')} Record counted cash</button></div></form>`);}
function detailModal(t){const events=state.audit.filter(a=>a.transactionId===t.id),others=state.transactions.filter(a=>a.referenceId===t.id);openModal('Transaction details',`<div class="group-row"><span class="pill ${t.type}">${activeTitle(t)}</span><strong>${amountView(t.delta)}</strong><span class="tag">Version ${t.version||1}</span></div><p class="small-note" style="margin-top:13px">${dateLong(t.date)} · Recorded ${new Date(t.createdAt).toLocaleString('en-PH')}</p><h3 style="margin:17px 0 8px">${esc(t.description)}</h3><div class="notice">Fund / paid from: ${esc(fundLabel(C.fundOf(t)))}<br>Category: ${esc(t.category||'—')}<br>Remarks: ${esc(t.remarks||'—')}<br>Transaction ID: ${esc(t.id)}${t.reversedBy?'<br>Reversed by: '+esc(t.reversedBy):''}</div>${t.lines?.length?`<table class="data-table" style="min-width:0;margin:15px 0"><thead><tr><th>Item</th><th>Qty</th><th>Price</th></tr></thead><tbody>${t.lines.map(l=>`<tr><td>${esc(l.name)}</td><td>${l.qty}</td><td>${money(l.price)}</td></tr>`).join('')}</tbody></table>`:''}${t.receipt?`<p class="small-note">Receipt image:</p><img class="receipt-img" alt="Expense receipt" src="${esc(t.receipt)}">`:''}${others.length?`<h3 style="margin:16px 0">Linked entries</h3>${others.map(x=>`<div class="activity"><strong>${activeTitle(x)}</strong><span style="margin-left:auto">${money(x.delta)}</span></div>`).join('')}`:''}<hr class="divider"><h3 style="margin-bottom:10px">Audit history (${events.length})</h3>${events.map(a=>`<div class="audit-item"><strong>${esc(a.action)}</strong><small>${new Date(a.date).toLocaleString('en-PH')} ${a.reason?'· '+esc(a.reason):''}</small><button class="text-btn" data-action="audit-detail" data-id="${a.id}">View before / after</button></div>`).join('')||'<p class="small-note">No changes recorded.</p>'}`);}
function refundModal(t){const past=state.transactions.filter(r=>r.type==='refund'&&r.referenceId===t.id).reduce((n,r)=>n-r.delta,0),remaining=t.delta-past;if(remaining<=0)return toast('This sale has already been fully refunded.',true);openModal('Refund sale / income',`<form id="refundForm" class="form-grid">${field('refundDate','Date of refund',today,'date','required')}${field('refundAmount','Amount returned (₱)',numPeso(remaining),'text','inputmode="decimal" required')}<div class="full notice">Original sale: ${money(t.delta)}<br>Previously refunded: ${money(past)}<br>Maximum remaining refund: <strong>${money(remaining)}</strong></div>${field('refundReason','Reason',`Refund — ${t.description}`,'text','required')}<input type="hidden" id="refundId" value="${esc(t.id)}"><div class="full form-footer"><button type="button" class="btn" data-action="modal-close">Cancel</button><button type="submit" class="btn btn-primary">${icon('check')} Record refund</button></div></form>`);}
function categoriesModal(){openModal('Expense categories',`<div class="notice">Create custom expense categories. Historical entries keep their original labels.</div><form id="categoryForm" class="form-grid" style="margin-top:14px"><input type="hidden" id="catKind" value="expense">${field('catName','New expense category','','text','required')}<div class="full form-footer"><button type="submit" class="btn btn-primary">${icon('plus')} Add category</button></div></form><hr class="divider"><div id="categoryList">${categoryListHtml('expense')}</div>`);}
function categoryListHtml(kind){const cats=kind==='sale'?state.saleCategories:state.expenseCategories,standard=kind==='sale'?C.SALE_CATS:C.EXPENSE_CATS;return cats.map(c=>`<div class="chip" style="margin:3px">${esc(c)}${!standard.includes(c)?`<button data-action="cat-rename" data-kind="${kind}" data-category="${esc(c)}" aria-label="Rename ${esc(c)}">${icon('edit')}</button><button data-action="cat-delete" data-kind="${kind}" data-category="${esc(c)}" aria-label="Delete ${esc(c)}">×</button>`:''}</div>`).join('');}
function pinModal(){const exists=!!state.settings.pin;openModal('Optional local PIN',`<div class="notice warn">This PIN is a convenience lock only. It does not encrypt the financial data stored in IndexedDB. Keep device-level protection enabled.</div><form id="pinForm" class="form-grid" style="margin-top:12px">${exists?field('currentPin','Current PIN','','password','minlength="4" maxlength="12" required'):''}${field('newPin','New PIN (4–12 digits; leave empty to remove)', '', 'password',`pattern="[0-9]{4,12}" ${exists?'':'required'}`)}<div class="full form-footer"><button type="button" class="btn" data-action="modal-close">Cancel</button><button type="submit" class="btn btn-primary">Save PIN</button></div></form>`);}
async function hashPIN(pin,salt){if(!globalThis.crypto?.subtle)throw Error('Secure cryptography is unavailable in this context. Use an HTTPS/local browser context to configure a PIN.');const key=await crypto.subtle.importKey('raw',new TextEncoder().encode(pin),'PBKDF2',false,['deriveBits']);const bits=await crypto.subtle.deriveBits({name:'PBKDF2',salt:new TextEncoder().encode(salt),iterations:110000,hash:'SHA-256'},key,256);return [...new Uint8Array(bits)].map(b=>b.toString(16).padStart(2,'0')).join('');}
function updateTheme(){
 const dark=state.settings.theme==='dark';
 document.documentElement.dataset.theme=dark?'dark':'light';
 document.querySelector('meta[name="theme-color"]').content=dark?'#151c19':'#fbfaf7';
 // Android native system bar text must stay readable with the chosen theme.
 // LIGHT = dark system text on a light header; DARK = light text on dark.
 const systemBars=globalThis.Capacitor?.Plugins?.SystemBars;
 if(systemBars?.setStyle) Promise.resolve(systemBars.setStyle({style:dark?'DARK':'LIGHT'})).catch(()=>{});
}
let pinAttempts=0;
function showLock(){if(!state.settings.pin)return;$('#lockScreen').classList.remove('hidden');$('#lockScreen').setAttribute('aria-hidden','false');$('#lockScreen').innerHTML=`<form id="unlockForm" class="lock-card"><div class="brandmark">${icon('lock')}</div><h2>Welcome back</h2><p>Enter your CanteenLedger PIN to unlock the workspace.</p><input type="password" pattern="[0-9]{4,12}" minlength="4" maxlength="12" autocomplete="off" name="pin" placeholder="Enter PIN" aria-label="CanteenLedger PIN" required><button class="btn btn-primary">Unlock CanteenLedger</button><p id="pinError" role="alert"></p></form>`;$('#lockScreen input')?.focus();}
async function exportBlob(blob,name){try{if(window.Capacitor?.isNativePlatform?.()&&window.Capacitor?.Plugins?.Filesystem&&window.Capacitor?.Plugins?.Share){const bytes=new Uint8Array(await blob.arrayBuffer());let b64='';for(let i=0;i<bytes.length;i+=16384)b64+=String.fromCharCode(...bytes.subarray(i,i+16384));const f=window.Capacitor.Plugins.Filesystem;await f.writeFile({path:name,data:btoa(b64),directory:'CACHE',recursive:true});const uri=await f.getUri({path:name,directory:'CACHE'});await window.Capacitor.Plugins.Share.share({title:'CanteenLedger '+name,url:uri.uri,dialogTitle:'Save or share your file'});toast('File prepared for sharing.');return;}const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.style.display='none';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);toast('File generated: '+name);}catch(e){console.error(e);toast('Export failed: '+e.message,true);}}
function isoFilename(s){return String(s).replace(/[^\w.-]/g,'_')};
async function downloadReport(fmt){try{const report=makeReport(),name=`CanteenLedger_${ui.reportType}_${ui.reportDate}.${fmt}`,blob=E[fmt](report);await exportBlob(blob,name);}catch(e){toast('Export error: '+e.message,true);}}
async function readReceipt(file){if(!file)return null;if(!file.type.startsWith('image/'))throw Error('Choose an image for the receipt.');if(file.size>12*1024*1024)throw Error('Choose an image under 12 MB.');const url=URL.createObjectURL(file);try{const img=new Image();img.src=url;await img.decode();const max=1380,scale=Math.min(1,max/Math.max(img.naturalWidth,img.naturalHeight)),c=document.createElement('canvas');c.width=Math.max(1,Math.round(img.naturalWidth*scale));c.height=Math.max(1,Math.round(img.naturalHeight*scale));const ctx=c.getContext('2d');ctx.fillStyle='white';ctx.fillRect(0,0,c.width,c.height);ctx.drawImage(img,0,0,c.width,c.height);return c.toDataURL('image/jpeg',.78);}finally{URL.revokeObjectURL(url);}}
function readySaleDraft(){return{date:$('#saleDate')?.value||ui.saleDraft.date,fund:$('#saleFund')?.value||ui.saleDraft.fund||'Food',amount:$('#saleAmount')?.value??ui.saleDraft.amount??'',correction:$('#saleCorrection')?.value??ui.saleDraft.correction??''};}
function resetSale(){ui.saleEdit=null;ui.saleDraft={date:today,fund:'Food',amount:'',correction:''};}
function startEdit(t){if(t.reversedBy)return toast('Reversed entries cannot be corrected.',true);if(state.transactions.some(r=>r.type==='refund'&&r.referenceId===t.id))return toast('This entry has refunds. Create a documented adjustment instead.',true);if(t.type==='sale'||t.type==='income'){ui.saleEdit=t.id;ui.saleDraft={date:t.date,fund:C.fundOf(t)==='Goods'?'Goods':'Food',amount:numPeso(t.delta),correction:''};page='sale';render();window.scrollTo(0,0);}else if(t.type==='expense'){ui.expenseEdit=t.id;ui.expenseReceipt=t.receipt||null;page='expense';render();window.scrollTo(0,0);}else if(t.type==='adjustment')adjustmentModal(t);else toast('This entry type cannot be edited. Reverse it and create a corrected entry.',true);}
async function submitSale(){if(busy)return;const data=readySaleDraft(),date=ensureDate(data.date),edit=ui.saleEdit?byId(ui.saleEdit):null;const next=C.makeSimpleSale({...data,date});if(edit&&edit.type!=='sale'&&edit.type!=='income')throw Error('Cannot change this transaction type.');const ok=await mutate(s=>{if(edit){const old=s.transactions.find(t=>t.id===edit.id),newVersion={...next,description:old.description,remarks:old.remarks||'',id:old.id,createdAt:old.createdAt,version:(old.version||1)+1,updatedAt:new Date().toISOString()};s.transactions[s.transactions.findIndex(t=>t.id===old.id)]=newVersion;audit(s,'Correct sale',old,newVersion,data.correction||'Corrected sales entry');}else{s.transactions.push(next);audit(s,'Record '+fundLabel(next.fund)+' sale',null,next);}},edit?'Correction saved to audit history':'Sales recorded offline');if(!ok)return;resetSale();page='dashboard';render();}
async function submitExpense(){const id=ui.expenseEdit,t=id?byId(id):null,date=ensureDate($('#expenseDate').value),amount=C.parseMoney($('#expenseAmount').value,{allowZero:false}),description=$('#expenseDescription').value.trim();if(!description)throw Error('Enter an expense description.');const next=C.makeExpense({date,amount:numPeso(amount),description,category:$('#expenseCategory').value,fund:$('#expenseFund').value,remarks:$('#expenseRemarks').value,receipt:ui.expenseReceipt??t?.receipt??null});const ok=await mutate(s=>{if(t){const old=s.transactions.find(x=>x.id===t.id),updated={...next,id:old.id,createdAt:old.createdAt,version:(old.version||1)+1};s.transactions[s.transactions.findIndex(x=>x.id===old.id)]=updated;audit(s,'Correct expense fund / amount',old,updated,$('#expenseCorrection')?.value||'');}else{s.transactions.push(next);audit(s,'Record expense paid from '+fundLabel(next.fund),null,next);}},t?'Expense corrected with audit history':'Expense deducted from '+fundLabel(next.fund));if(!ok)return;ui.expenseEdit=null;ui.expenseReceipt=null;page='dashboard';render();}
async function submitAdjustment(){const id=$('#adjustForm [name=editId]').value,date=ensureDate($('#adjustDate').value),description=$('#adjustReason').value.trim(),amount=$('#adjustAmount').value,remarks=$('#adjustNotes').value;if(!description)throw Error('Provide a reason for the adjustment.');const next=C.makeAdjustment({date,reason:description,amount,remarks,fund:$('#adjustFund').value});const ok=await mutate(s=>{const old=s.transactions.find(t=>t.id===id);if(old){const updated={...next,id:old.id,createdAt:old.createdAt,version:old.version+1};s.transactions[s.transactions.findIndex(t=>t.id===old.id)]=updated;audit(s,'Correct adjustment',old,updated,$('#adjustCorrection')?.value||'');}else{s.transactions.push(next);audit(s,'Cash adjustment / opening balance',null,next);}},'Cash adjustment recorded');if(ok)closeModal();}
async function submitClosing(){const date=ensureDate($('#closingDate').value),counted=C.parseMoney($('#closingCounted').value),expected=C.balance(state.transactions,C.addDays(date,1)),note=$('#closingRemarks').value;const ok=await mutate(s=>{const old=s.closings.findLast?.(x=>x.date===date);const record={id:C.uid(),date,counted,expected,difference:counted-expected,remarks:note,createdAt:new Date().toISOString()};s.closings.push(record);audit(s,'End-of-day cash count',old,record,note);},'End-of-day count saved');if(ok)closeModal();}
async function submitRefund(){const t=byId($('#refundId').value),date=ensureDate($('#refundDate').value),amount=C.parseMoney($('#refundAmount').value,{allowZero:false}),prev=state.transactions.filter(r=>r.type==='refund'&&r.referenceId===t.id).reduce((s,r)=>s-r.delta,0);if(t.reversedBy||amount>t.delta-prev)throw Error('Refund exceeds the remaining refundable amount.');const reason=$('#refundReason').value.trim();if(!reason)throw Error('Enter a refund reason.');const tx=C.newTx('refund',{date,description:reason,category:'Refund',delta:-amount,fund:C.fundOf(t),referenceId:t.id,remarks:reason});const ok=await mutate(s=>{s.transactions.push(tx);audit(s,'Refund for '+t.id,null,tx,reason);},'Refund recorded; original retained');if(ok)closeModal();}
async function submitCategory(){const kind=$('#catKind').value,name=$('#catName').value.trim(),key=kind==='sale'?'saleCategories':'expenseCategories';if(!name||name.length>70)throw Error('Choose a category name under 70 characters.');if(state[key].some(x=>x.toLowerCase()===name.toLowerCase()))throw Error('Category already exists.');const ok=await mutate(s=>{s[key].push(name);audit(s,'Add '+kind+' category',null,{id:C.uid(),name});},'Category saved');if(ok)categoriesModal();}
async function submitSettings(){const name=$('#schoolName').value.trim();if(!name)throw Error('Enter a school or canteen name.');const config={school:name,preparedBy:$('#preparedBy').value,reviewedBy:$('#reviewedBy').value,theme:$('#themeSelect').value};await mutate(s=>{Object.assign(s.settings,config);},'Preferences saved');}
async function submitPin(){const original=state.settings.pin,current=$('#currentPin')?.value||'',next=$('#newPin').value;if(original&&await hashPIN(current,original.salt)!==original.hash)throw Error('Current PIN is incorrect.');if(next&&!/^\d{4,12}$/.test(next))throw Error('Choose 4–12 digits.');const pin=next?{salt:C.uid(),hash:''}:null;if(pin)pin.hash=await hashPIN(next,pin.salt);const ok=await mutate(s=>{s.settings.pin=pin;},pin?'PIN updated':'PIN removed');if(ok)closeModal();}
async function actionClick(el){const action=el.dataset.action,id=el.dataset.id;
 switch(action){
 case 'nav':go(el.dataset.page);break;
 case 'chart-period':ui.chart=el.dataset.value;render();break;
 case 'week-shift':ui.week=C.addDays(ui.week,Number(el.dataset.delta));render();break;
 case 'month-shift':{const [y,m]=ui.month.split('-').map(Number),d=new Date(y,m-1+Number(el.dataset.delta),1);ui.month=C.isoDate(d).slice(0,7);render();break;}
 case 'coop-money':coopMoneyModal();break;
 case 'member-add':memberModal(null);break;
 case 'member-edit':memberModal(state.members.find(m=>m.id===id));break;
 case 'member-toggle':{const m=state.members.find(m=>m.id===id);if(!m)break;ask(m.archived?'Restore member?':'Remove member?',m.archived?'Restore this member to the active list?':'This hides the member from active selection but preserves their name in all historical transactions.',async()=>{await mutate(s=>{const x=s.members.find(y=>y.id===id),before=structuredClone(x);x.archived=!x.archived;audit(s,x.archived?'Remove cooperative member':'Restore cooperative member',before,x);},'Member list updated');},m.archived?'Restore':'Remove',!m.archived);break;}
 case 'cancel-edit':ui.saleEdit=null;ui.expenseEdit=null;ui.expenseReceipt=null;resetSale();go('transactions');break;
 case 'remove-receipt':ui.expenseReceipt='';$('#receiptPreview').innerHTML='';break;
 case 'clear-filters':ui.history={search:'',type:'all',from:'',to:'',min:'',max:'',category:'all'};render();break;
 case 'adjust':adjustmentModal(null);break;
 case 'closing':closingModal();break;
 case 'tx-detail':detailModal(byId(id));break;
 case 'tx-edit':startEdit(byId(id));break;
 case 'tx-reverse':{const t=byId(id);if(state.transactions.some(r=>r.type==='refund'&&r.referenceId===t.id)){toast('Refunds exist for this entry. Use a separate documented adjustment instead of reversing it.',true);break;}ask('Reverse this transaction?',`This will create a new opposite cash entry for ${money(Math.abs(t.delta))}. The original transaction and audit trail will remain.`,async()=>{await mutate(s=>{const old=s.transactions.find(x=>x.id===id),reversal=C.reversal(old,'Reversed by treasurer');old.reversedBy=reversal.id;s.transactions.push(reversal);audit(s,'Reverse transaction',null,reversal,`Reverses ${id}`);},'Reversal recorded');},'Reverse entry',true);break;}
 case 'refund':refundModal(byId(id));break;
 case 'audit-detail':{const a=state.audit.find(x=>x.id===id);if(!a)break;openModal('Audit history · '+a.action,`<p class="small-note">${new Date(a.date).toLocaleString('en-PH')}${a.reason?' · '+esc(a.reason):''}</p><h3 style="margin:14px 0">Original values</h3><pre style="overflow:auto;background:var(--panel);border:1px solid var(--border);padding:13px;border-radius:9px;font-size:10px">${esc(a.before?JSON.stringify(a.before,null,2):'New entry')}</pre><h3 style="margin:14px 0">Updated values</h3><pre style="overflow:auto;background:var(--panel);border:1px solid var(--border);padding:13px;border-radius:9px;font-size:10px">${esc(a.after?JSON.stringify(a.after,null,2):'No new record')}</pre>`);break;}
 case 'report-update':{ui.reportType=$('#reportType').value;ui.reportDate=$('#reportDate').value;ensureDate(ui.reportDate);render();break;}
 case 'export-report':await downloadReport(el.dataset.format);break;
 case 'print-report':window.print();break;
 case 'backup':{const blob=new Blob([JSON.stringify({...state,backupDate:new Date().toISOString()},null,2)],{type:'application/json'});await exportBlob(blob,`CanteenLedger-backup-${today}.json`);break;}
 case 'restore':$('#restoreInput')?.click();break;
 case 'persist-storage':{if(navigator.storage?.persist){const ok=await navigator.storage.persist();toast(ok?'Persistent storage granted; backups are still essential.':'Browser did not grant persistent storage. Make regular backups.',!ok);}else toast('Persistent storage is not supported here. Make regular backups.',true);break;}
 case 'pin':pinModal();break;
 case 'categories':categoriesModal();break;
 case 'cat-rename':{const kind=el.dataset.kind,old=el.dataset.category;openModal('Rename custom category',`<form id="renameCategoryForm" class="form-grid"><input type="hidden" id="renameKind" value="${esc(kind)}"><input type="hidden" id="renameOld" value="${esc(old)}">${field('renameValue','New category name',old,'text','required maxlength="70"')}<div class="full form-footer"><button class="btn" type="button" data-action="modal-close">Cancel</button><button class="btn btn-primary" type="submit">Save name</button></div></form><p class="small-note">Previous transaction categories will not be rewritten.</p>`);break;}
 case 'cat-delete':{const kind=el.dataset.kind,name=el.dataset.category,standard=kind==='sale'?C.SALE_CATS:C.EXPENSE_CATS;if(standard.includes(name))return;ask('Delete custom category?',`Remove “${name}” from the available category list? Historical entries will retain their labels; current products in this category will be assigned to Other Goods.`,async()=>{await mutate(s=>{const key=kind==='sale'?'saleCategories':'expenseCategories';s[key]=s[key].filter(x=>x!==name);if(kind==='sale')s.products.forEach(p=>{if(p.category===name)p.category='Other Goods'});audit(s,'Delete '+kind+' category',{name},null,'Historical categories preserved');},'Category deleted');categoriesModal();},'Delete',true);break;}
 case 'modal-close':closeModal();break;
 case 'confirm-run':{const cb=confirmCallback;confirmCallback=null;closeModal();if(cb)await cb();break;}
 default:break;}}
async function onSubmit(e){const form=e.target;if(!form.id)return;e.preventDefault();try{if(form.id==='saleForm')await submitSale();else if(form.id==='coopForm')await submitCoop();else if(form.id==='memberForm')await submitMember();else if(form.id==='expenseForm')await submitExpense();else if(form.id==='adjustForm')await submitAdjustment();else if(form.id==='closingForm')await submitClosing();else if(form.id==='refundForm')await submitRefund();else if(form.id==='categoryForm')await submitCategory();else if(form.id==='renameCategoryForm'){const kind=$('#renameKind').value,old=$('#renameOld').value,value=$('#renameValue').value.trim(),key=kind==='sale'?'saleCategories':'expenseCategories';if(!value||value.length>70)throw Error('Enter a name up to 70 characters.');if(state[key].some(x=>x.toLowerCase()===value.toLowerCase()&&x!==old))throw Error('That category already exists.');const ok=await mutate(s=>{const i=s[key].indexOf(old);if(i<0)throw Error('Category no longer exists.');s[key][i]=value;if(kind==='sale')s.products.forEach(p=>{if(p.category===old)p.category=value});audit(s,'Rename '+kind+' category',{name:old},{name:value},'Historical categories preserved');},'Category renamed');if(ok)categoriesModal();}else if(form.id==='settingsForm')await submitSettings();else if(form.id==='pinForm')await submitPin();else if(form.id==='unlockForm'){const entered=form.pin?.value||$('[name="pin"]',form).value;const hash=await hashPIN(entered,state.settings.pin.salt);if(hash===state.settings.pin.hash){$('#lockScreen').classList.add('hidden');$('#lockScreen').setAttribute('aria-hidden','true');$('#lockScreen').innerHTML='';pinAttempts=0;}else{pinAttempts++;$('#pinError').textContent=pinAttempts>=5?'Too many incorrect attempts. Try again after reopening the app.':'Incorrect PIN.';if(pinAttempts>=5)$('button',form).disabled=true;}}}catch(ex){console.error(ex);toast(ex.message||'Please verify the information.',true);}}
function filterOnChange(el){const key=el.dataset.filter;if(key){ui.history[key]=el.value;render();return true;}if(el.dataset.input){const k=el.dataset.input;ui[k]=k==='showArchived'?el.checked:el.value;render();return true;}return false;}
let searchTimer;
document.addEventListener('input',e=>{const el=e.target;if(el.id==='closingCounted'||el.id==='closingDate'){const d=$('#closingDate')?.value;const expected=validDate(d)?C.balance(state.transactions,C.addDays(d,1)):0;if($('#closingExpected'))$('#closingExpected').textContent=money(expected);try{const counted=C.parseMoney($('#closingCounted').value);$('#closingDiff').textContent=money(counted-expected);}catch{$('#closingDiff').textContent='—';}return;}if(el.dataset.filter==='search'||el.dataset.input==='productSearch'){const key=el.dataset.filter||el.dataset.input;ui[el.dataset.filter?'history': 'productSearch']=el.dataset.filter?{...ui.history,[key]:el.value}:el.value;const focus=el.selectionStart;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{render();const target=$('[data-filter="search"]')||$('[data-input="productSearch"]');target?.focus();try{target?.setSelectionRange(focus,focus)}catch{}},350);}});
document.addEventListener('change',async e=>{const el=e.target;try{if(el.dataset.operating){const date=el.dataset.operating,checked=el.checked;await mutate(s=>{s.operatingDays[date]=checked;},checked?'Marked as operating day':'Operating day unmarked');return;}if(el.id==='expenseReceipt'&&el.files?.[0]){ui.expenseReceipt=await readReceipt(el.files[0]);$('#receiptPreview').innerHTML=`<img class="receipt-preview" src="${esc(ui.expenseReceipt)}" alt="Receipt preview"><button type="button" class="btn btn-small" data-action="remove-receipt">Remove receipt</button>`;return;}if(el.id==='restoreInput'&&el.files?.[0]){const f=el.files[0];if(f.size>80*1024*1024)throw Error('Backup file is too large (80 MB maximum).');const imported=C.normalized(JSON.parse(await f.text()));ask('Replace ALL current data?',`This will replace ${state.transactions.length} current transactions with ${imported.transactions.length} transactions from the selected backup. Download a current backup first.`,async()=>{const ok=await mutate(s=>{for(const k of Object.keys(s))delete s[k];Object.assign(s,imported);},'Backup restored');if(ok){closeModal();if(state.settings.pin)showLock();}},'Restore backup',true);el.value='';return;}if(el.id==='reportType')ui.reportType=el.value;if(el.id==='reportDate')ui.reportDate=el.value;if(el.dataset.filter){filterOnChange(el);return;}if(el.dataset.input&&el.dataset.input!=='productSearch'){filterOnChange(el);return;}}catch(ex){toast(ex.message||'Could not process file.',true);}});
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(el){e.preventDefault();try{await actionClick(el);}catch(ex){console.error(ex);toast(ex.message||'Action failed.',true);}return;}if(e.target.matches('[data-overlay]'))closeModal();const bar=e.target.closest('[data-chart]');if(bar){const label=bar.querySelector('title')?.textContent||bar.getAttribute('aria-label');openModal('Chart details',`<p style="margin:0">${esc(label)}</p>`, '<button class="btn" data-action="modal-close">Close</button>',true);}});
document.addEventListener('submit',onSubmit);
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();}if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-chart]')){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));}});
async function init(){try{db=await openDB();state=C.normalized((await dbGet())||C.blank());updateTheme();render();showLock();}catch(ex){console.error(ex);$('#main').innerHTML=`<div class="content"><div class="card card-pad"><h1>Could not open offline storage</h1><p class="subtitle">${esc(ex.message)}</p><p>Please use a current browser that supports IndexedDB. Avoid private browsing modes that block local storage. If you have a backup, keep it safe until you can restore it.</p></div></div>`;toast('Offline storage is unavailable.',true);}}
init();
})();
